import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1787003086000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>FRESHRSS_URL</code></td><td>yes</td><td>—</td><td>Root URL of the FreshRSS instance, e.g. <code>https://rss.example.com</code></td></tr><tr><td><code>FRESHRSS_USER</code></td><td>yes</td><td>—</td><td>FreshRSS user name</td></tr><tr><td><code>FRESHRSS_API_PASSWORD</code></td><td>yes</td><td>—</td><td>The API password from Settings → Profile → API management</td></tr><tr><td><code>FRESHRSS_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the eight read tools</td></tr><tr><td><code>FRESHRSS_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts a self-signed certificate, scoped to this connection</td></tr></tbody></table><p>There is no configuration file and no command-line flag; these are the whole surface. The reasoning behind each is in <a href="/guide/configuration">Configuration</a>.</p><h2 id="validation-at-startup" tabindex="-1">Validation at startup <a class="header-anchor" href="#validation-at-startup" aria-label="Permalink to “Validation at startup”">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Result</th></tr></thead><tbody><tr><td>A required variable is missing</td><td>Warning; the server starts and lists tools</td></tr><tr><td><code>FRESHRSS_URL</code> does not parse</td><td><strong>Exit 1</strong> (the value is logged with credentials redacted)</td></tr><tr><td><code>FRESHRSS_URL</code> scheme is not <code>http</code>/<code>https</code></td><td><strong>Exit 1</strong></td></tr><tr><td><code>FRESHRSS_URL</code> contains <code>user:password@</code></td><td><strong>Exit 1</strong></td></tr><tr><td><code>FRESHRSS_URL</code> is plain http to a non-loopback host</td><td>Warning about the unencrypted API password</td></tr><tr><td><code>FRESHRSS_INSECURE_TLS=true</code></td><td>Warning that certificate validation is relaxed</td></tr></tbody></table><p>A missing credential is deliberately not fatal: the server must be able to complete the MCP handshake and answer <code>tools/list</code> without one, so registries and sandbox inspectors can introspect it. Every tool call then fails with the setup instructions. A malformed URL <em>is</em> fatal — that one could send the API password to the wrong host.</p><p>All diagnostics go to <strong>stderr</strong>, which is where MCP stdio servers must log — stdout carries the protocol.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>Only the exact string <code>true</code> enables <code>FRESHRSS_READ_ONLY</code> and <code>FRESHRSS_INSECURE_TLS</code>; anything else, including <code>1</code> and <code>yes</code>, leaves them off.</li><li>Trailing slashes on <code>FRESHRSS_URL</code> are stripped.</li><li>The API path <code>/api/greader.php</code> is appended automatically — do not include it.</li><li><code>FRESHRSS_API_PASSWORD</code> is <strong>deleted from <code>process.env</code></strong> once the configuration has been read, on every path including the ones that then exit. It would otherwise stay readable by child processes and in <code>/proc/&lt;pid&gt;/environ</code>.</li><li>Requests use a 30-second timeout (120 seconds for <code>subscribe_feed</code> and <code>import_opml</code>, which make FreshRSS fetch from the internet first) and refuse to follow redirects.</li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits”">​</a></h2><p>Not configurable, but they bound every response:</p><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th></tr></thead><tbody><tr><td>Articles per listing</td><td>100 (default 20)</td></tr><tr><td>Ids per <code>get_articles</code></td><td>20</td></tr><tr><td>Articles per <code>mark_articles</code></td><td>100</td></tr><tr><td>Article text per article</td><td>20 000 characters (default 2000)</td></tr><tr><td>Excerpt length</td><td>300 characters</td></tr><tr><td>Article text per response</td><td>60 000 characters</td></tr><tr><td>Serialised tool result</td><td>400 000 characters</td></tr><tr><td>OPML export</td><td>200 000 characters</td></tr><tr><td>OPML import</td><td>900 000 characters</td></tr><tr><td>Confirmation token lifetime</td><td>5 minutes, single use</td></tr></tbody></table><p>The OPML import limit sits below the 1 048 576 bytes FreshRSS reads from <code>php://input</code> — beyond that it truncates silently, which would arrive as malformed XML.</p>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};